import csv
import re
from datetime import date

EMAIL = r"[^@\s]+@[^@\s]+\.[^@\s]+"

def clean_name(text):
    return " ".join(text.split()).title()

def clean_email(text):
    email = text.strip().lower()
    if re.fullmatch(EMAIL, email):
        return email
    return None

def clean_phone(text):
    digits = ""
    for ch in text:
        if ch.isdigit():
            digits = digits + ch
    if len(digits) == 10:
        return digits
    return None

def parse_amount(text):
    return float(text.strip().replace("$", "").replace(",", ""))

def clean_row(row):
    return {
        "name": clean_name(row["name"]),
        "email": clean_email(row["email"]),
        "phone": clean_phone(row["phone"]),
        "amount": parse_amount(row["amount_due"]),
        "due": row["due_date"].strip(),
        "paid": row["paid"].strip().lower() == "yes",
    }

def remove_duplicates(rows):
    seen = []
    unique = []
    for row in rows:
        email = row["email"]
        if email is not None and email in seen:
            continue
        seen.append(email)
        unique.append(row)
    return unique

def days_between(start, end):
    return (date.fromisoformat(end) - date.fromisoformat(start)).days

def money(x):
    return f"${x:,.2f}"

def days_late(item):
    return item[1]

def late_customers(rows, today):
    late = []
    for row in rows:
        days = days_between(row["due"], today)
        if not row["paid"] and days > 0:
            late.append((row["name"], days, row["amount"]))
    late.sort(key=days_late, reverse=True)
    return late

def make_report(rows, today):
    unpaid_count = 0
    unpaid_total = 0
    for row in rows:
        if not row["paid"]:
            unpaid_count = unpaid_count + 1
            unpaid_total = unpaid_total + row["amount"]

    late = late_customers(rows, today)
    late_total = 0
    for name, days, amount in late:
        late_total = late_total + amount

    lines = [
        f"CUSTOMER REPORT - {today}",
        f"Customers: {len(rows)}",
        f"Unpaid: {unpaid_count} customers, {money(unpaid_total)}",
        f"Late: {len(late)} customers, {money(late_total)}",
        "",
        "LATE PAYMENTS",
    ]
    for name, days, amount in late:
        lines.append(f"{name:<15}{days:>3} days {money(amount):>11}")
    return "\n".join(lines)

today = date.today().isoformat()

with open("customers.csv", newline="") as f:      # your original file is only READ
    rows = remove_duplicates([clean_row(r) for r in csv.DictReader(f)])

with open("clean_customers.csv", "w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=["name", "email", "phone", "amount", "due", "paid"])
    writer.writeheader()
    for row in rows:
        writer.writerow(row)

report = make_report(rows, today)
with open("report.txt", "w") as f:
    f.write(report)
print(report)

